using System.Text.Json;
using LexiSharp.Classification;
using LexiSharp.Core;
using LexiSharp.Eval;
using Xunit;

namespace LexiSharp.Tests;

/// <summary>
/// Differential tests for the classification statistics against scipy.
/// </summary>
/// <remarks>
/// The fixtures are generated by <c>scripts/generate-classification-stats-fixtures.py</c> and
/// checked in, so the test suite needs no Python or scipy. McNemar is the asymptotic
/// continuity-corrected test the harness reports; temperature scaling is the grid search the
/// library ships. The temperature assertion allows one grid step (the shipped grid is 400 steps
/// over [0.05, 10], so 0.05 is a safe bound).
/// </remarks>
public class ClassificationStatsDifferentialTests
{
    private sealed class McNemarFixture
    {
        public string Source { get; init; } = string.Empty;

        public string Version { get; init; } = string.Empty;

        public List<McNemarCase> Cases { get; init; } = [];
    }

    private sealed class McNemarCase
    {
        public string Name { get; init; } = string.Empty;

        public int BaselineOnly { get; init; }

        public int CandidateOnly { get; init; }

        public double ExpectedPValue { get; init; }
    }

    private sealed class TemperatureFixture
    {
        public string Source { get; init; } = string.Empty;

        public string Version { get; init; } = string.Empty;

        public List<TemperatureCase> Cases { get; init; } = [];
    }

    private sealed class TemperatureCase
    {
        public string Name { get; init; } = string.Empty;

        public List<TemperatureSample> Samples { get; init; } = [];

        public double ExpectedTemperature { get; init; }

        public double ExpectedLogLoss { get; init; }
    }

    private sealed class TemperatureSample
    {
        public string Actual { get; init; } = string.Empty;

        public List<DistributionEntry> Distribution { get; init; } = [];
    }

    private sealed class DistributionEntry
    {
        public string Category { get; init; } = string.Empty;

        public double Probability { get; init; }
    }

    [Fact]
    public void McNemar_MatchesScipyAsymptoticWithContinuityCorrection()
    {
        McNemarFixture fixture = Load<McNemarFixture>("mcnemar-scipy.json");
        Assert.Equal("scipy.stats.chi2", fixture.Source);
        Assert.NotEmpty(fixture.Cases);

        foreach (McNemarCase test in fixture.Cases)
        {
            var documents = new List<ClassificationDocument>();
            var baseline = new List<string?>();
            var candidate = new List<string?>();

            for (int i = 0; i < test.BaselineOnly; i++)
            {
                documents.Add(new ClassificationDocument($"b{i}", string.Empty, "A"));
                baseline.Add("A");
                candidate.Add("B");
            }

            for (int i = 0; i < test.CandidateOnly; i++)
            {
                documents.Add(new ClassificationDocument($"c{i}", string.Empty, "A"));
                baseline.Add("B");
                candidate.Add("A");
            }

            for (int i = 0; i < 5; i++)
            {
                documents.Add(new ClassificationDocument($"same{i}", string.Empty, "A"));
                baseline.Add("A");
                candidate.Add("A");
            }

            McNemarResult result = ClassificationEvaluation.McNemar(
                documents, baseline, candidate, "baseline", "candidate");

            Assert.Equal(test.BaselineOnly, result.BaselineOnly);
            Assert.Equal(test.CandidateOnly, result.CandidateOnly);
            // Erfc is the Numerical Recipes approximation (about 1e-7), so the
            // differential check is to six decimals, not to the last bit.
            Assert.Equal(test.ExpectedPValue, result.PValue, 6);
        }
    }

    [Fact]
    public void TemperatureCalibrator_MatchesTheScipyOptimum()
    {
        TemperatureFixture fixture = Load<TemperatureFixture>("temperature-scipy.json");
        Assert.Equal("scipy.optimize.minimize_scalar", fixture.Source);
        Assert.NotEmpty(fixture.Cases);

        foreach (TemperatureCase test in fixture.Cases)
        {
            var samples = test.Samples
                .Select(sample => new CalibrationSample(
                    sample.Distribution
                        .Select(entry => new ClassificationResult(entry.Category, entry.Probability))
                        .ToList(),
                    sample.Actual))
                .ToList();

            TemperatureCalibrator calibrator = TemperatureCalibrator.Fit(samples);
            double loss = MeanLogLoss(calibrator, samples);

            Assert.True(
                Math.Abs(calibrator.Temperature - test.ExpectedTemperature) <= 0.05,
                $"{test.Name}: temperature expected {test.ExpectedTemperature:R}, got {calibrator.Temperature:R}");

            Assert.True(
                Math.Abs(loss - test.ExpectedLogLoss) <= 1e-3,
                $"{test.Name}: log-loss expected {test.ExpectedLogLoss:R}, got {loss:R}");
        }
    }

    private static double MeanLogLoss(
        TemperatureCalibrator calibrator,
        IReadOnlyList<CalibrationSample> samples)
    {
        double loss = 0;

        foreach (CalibrationSample sample in samples)
        {
            IReadOnlyList<ClassificationResult> calibrated = calibrator.Calibrate(sample.Distribution);
            double probability = calibrated
                .First(result => result.Category == sample.Actual)
                .Probability;

            loss -= Math.Log(Math.Max(probability, 1e-12));
        }

        return loss / samples.Count;
    }

    private static T Load<T>(string fileName)
    {
        string path = Path.Combine(AppContext.BaseDirectory, "TestData", fileName);

        return JsonSerializer.Deserialize<T>(
            File.ReadAllText(path),
            new JsonSerializerOptions { PropertyNameCaseInsensitive = true })
            ?? throw new InvalidOperationException($"The {fileName} fixture is empty.");
    }
}
